CREATE TABLE IF NOT EXISTS gis_phase359_authoritative_layer (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), source_id TEXT NOT NULL UNIQUE, provider TEXT, semantic_class TEXT, confidence DOUBLE PRECISION NOT NULL DEFAULT 0, selection_status TEXT NOT NULL, rationale JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE TABLE IF NOT EXISTS gis_phase359_crosswalk_quarantine (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id UUID NOT NULL UNIQUE, prior_crosswalk_version TEXT NOT NULL, quarantine_reason TEXT NOT NULL, source_feature_id UUID, target_feature_id UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now());